{"file_path":"src/diff.js","content":"/**
 * Diffs a side document against the base with a longest common subsequence
 * over whole lines, then reports the stretches the subsequence does not
 * cover as changes: a run of base lines replaced by a run of the side's
 * lines.
 */

/**
 * Returns the changes needed to turn `base` into `side`, each as
 * `{ baseStart, baseEnd, lines }` where `baseStart`/`baseEnd` are the
 * (exclusive-end) range of base lines the change replaces and `lines` are
 * the side's lines that replace them, in base order.
 */
export function computeChanges(base, side) {
  const m = base.length
  const n = side.length

  // dp[i][j] is the length of the longest common subsequence of
  // base[i:] and side[j:].
  const dp = new Array(m + 1)
  for (let i = 0; i <= m; i++) dp[i] = new Array(n + 1).fill(0)
  for (let i = m - 1; i >= 0; i--) {
    for (let j = n - 1; j >= 0; j--) {
      dp[i][j] = base[i] === side[j] ? dp[i + 1][j + 1] + 1 : Math.max(dp[i + 1][j], dp[i][j + 1])
    }
  }

  const changes = []
  let i = 0
  let j = 0
  let baseStart = 0
  let sideStart = 0

  while (i < m && j < n) {
    if (base[i] === side[j]) {
      if (i > baseStart || j > sideStart) {
        changes.push({ baseStart, baseEnd: i, lines: side.slice(sideStart, j) })
      }
      i++
      j++
      baseStart = i
      sideStart = j
    } else if (dp[i + 1][j] >= dp[i][j + 1]) {
      i++
    } else {
      j++
    }
  }

  if (baseStart < m || sideStart < n) {
    changes.push({ baseStart, baseEnd: m, lines: side.slice(sideStart, n) })
  }

  return changes
}
"}

