 * Groups the changes from both sides into regions and resolves each region
 * against the base document.
 */

/**
 * Merges `mineChanges` and `theirsChanges`, tagged with their side, into
 * regions: maximal runs of overlapping changes, ordered by where they start
 * in the base. Changes from mine sort before changes from theirs when they
 * start at the same place.
 */
function buildRegions(mineChanges, theirsChanges) {
  const all = [
    ...mineChanges.map(change => ({ ...change, side: 'mine' })),
    ...theirsChanges.map(change => ({ ...change, side: 'theirs' })),
  ].sort((a, b) => {
    if (a.baseStart !== b.baseStart) return a.baseStart - b.baseStart
    if (a.side === b.side) return 0
    return a.side === 'mine' ? -1 : 1
  })

  const regions = []
  let index = 0
  while (index < all.length) {
    const first = all[index]
    let baseStart = first.baseStart
    let baseEnd = first.baseEnd
    const changes = [first]
    index++
    while (index < all.length && all[index].baseStart <= baseEnd) {
      const next = all[index]
      baseEnd = Math.max(baseEnd, next.baseEnd)
      changes.push(next)
      index++
    }
    regions.push({ baseStart, baseEnd, changes })
  }

  return regions
}

/**
 * Returns the lines `side` contributes across `region`: the base lines the
 * region covers, with each of that side's own changes spliced in.
 */
function sideLinesFor(region, base, side) {
  const changes = region.changes.filter(change => change.side === side)
  const out = []
  let cursor = region.baseStart
  for (const change of changes) {
    out.push(...base.slice(cursor, change.baseStart))
    out.push(...change.lines)
    cursor = change.baseEnd
  }
  out.push(...base.slice(cursor, region.baseEnd))
  return out
}

function arraysEqual(a, b) {
  if (a.length !== b.length) return false
  for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) return false
  return true
}

/**
 * Resolves a region: `{ type: 'both' | 'mine' | 'theirs', lines }` when it
 * merges cleanly, or `{ type: 'conflict', mine, base, theirs }` when it does
 * not.
 */
function resolveRegion(region, base) {
  const mine = sideLinesFor(region, base, 'mine')
  const theirs = sideLinesFor(region, base, 'theirs')
  const baseLines = base.slice(region.baseStart, region.baseEnd)

  if (arraysEqual(mine, theirs)) return { type: 'both', lines: mine }
  if (arraysEqual(mine, baseLines)) return { type: 'theirs', lines: theirs }
  if (arraysEqual(theirs, baseLines)) return { type: 'mine', lines: mine }
  return { type: 'conflict', mine, base: baseLines, theirs }
}

/**
 * Builds the ordered list of segments covering the whole base document:
 * `{ type: 'stable', lines }` for stable stretches and
 * `{ type: 'region', resolved }` for each resolved region.
 */
export function buildSegments(base, mineChanges, theirsChanges) {
  const regions = buildRegions(mineChanges, theirsChanges)

  const segments = []
  let cursor = 0
  for (const region of regions) {
    if (region.baseStart > cursor) segments.push({ type: 'stable', lines: base.slice(cursor, region.baseStart) })
    segments.push({ type: 'region', resolved: resolveRegion(region, base) })
    cursor = region.baseEnd
  }
  if (cursor < base.length) segments.push({ type: 'stable', lines: base.slice(cursor, base.length) })

  return segments
}
"}

